namespace GestionMagasin.Domain;

public interface IRepository<T> where T : class { Task<T?> GetByIdAsync(Guid id, CancellationToken ct = default); }
public interface IUtilisateurRepository : IRepository<Utilisateur> { Task<Utilisateur?> AuthentifierAsync(string nom, string motDePasse, CancellationToken ct = default); Task<IReadOnlyList<Utilisateur>> ListerAsync(CancellationToken ct = default); Task AjouterAsync(Utilisateur utilisateur, string motDePasse, CancellationToken ct = default); Task ModifierAsync(Utilisateur utilisateur, string? nouveauMotDePasse, CancellationToken ct = default); Task<bool> ExisteAdministrateurActifAsync(CancellationToken ct = default); }
public interface ICategorieRepository : IRepository<Categorie> { Task<IReadOnlyList<Categorie>> ListerAsync(CancellationToken ct = default); Task AjouterAsync(Categorie categorie, CancellationToken ct = default); Task ModifierAsync(Categorie categorie, CancellationToken ct = default); }
public interface IProduitRepository : IRepository<Produit> { Task<IReadOnlyList<Produit>> RechercherAsync(ProduitFilter filtre, CancellationToken ct = default); Task AjouterAsync(Produit produit, CancellationToken ct = default); Task ModifierAsync(Produit produit, CancellationToken ct = default); }
public interface IVenteRepository : IRepository<Vente> { Task<VenteResultat> ValiderAsync(Utilisateur vendeur, IReadOnlyList<PanierLigne> panier, string modePaiement, long montantRecuFcfa, string fuseauHoraire, CancellationToken ct = default); Task<IReadOnlyList<VenteHistorique>> RechercherAsync(string? numero, DateTime? du, DateTime? au, Guid? vendeurId, string? statut, Utilisateur acteur, CancellationToken ct = default); Task<VenteDetail?> ObtenirDetailAsync(Guid venteId, CancellationToken ct = default); Task AnnulerAsync(Guid venteId, Utilisateur administrateur, string motif, CancellationToken ct = default); }
public interface IStockRepository { Task<int> ObtenirStockAsync(Guid produitId, CancellationToken ct = default); Task<IReadOnlyList<MouvementStockDto>> ListerAsync(Guid? produitId = null, CancellationToken ct = default); Task AjouterMouvementAsync(MouvementStock mouvement, CancellationToken ct = default); }
public interface IAuditRepository { Task JournaliserAsync(JournalAudit entree, CancellationToken ct = default); }
public interface IDatabaseInitializer { Task InitializeAsync(CancellationToken ct = default); }
public interface IHorloge { DateTime UtcNow { get; } }
public interface IReportingRepository { Task<DashboardMetrics> DashboardAsync(Utilisateur acteur, DateTime jourMetier, string fuseauHoraire, CancellationToken ct = default); Task<IReadOnlyList<RapportProduit>> VentesParProduitAsync(Utilisateur acteur, DateTime debutMetier, DateTime finMetier, string fuseauHoraire, CancellationToken ct = default); Task<RapportSynthese> SyntheseAsync(Utilisateur acteur, DateTime debutMetier, DateTime finMetier, string fuseauHoraire, CancellationToken ct = default); Task<IReadOnlyList<MouvementStockDto>> StockAsync(CancellationToken ct = default); }
public interface ISettingsRepository { Task<ParametresMagasin> ObtenirAsync(CancellationToken ct = default); Task EnregistrerAsync(ParametresMagasin parametres, CancellationToken ct = default); }
public interface IAuditWriter { Task EcrireAsync(AuditEntry entry, CancellationToken ct = default); }
public interface IBackupManager { Task<SauvegardeInfo> SauvegarderAsync(string destination, string type, Guid? utilisateurId, CancellationToken ct = default); Task VerifierAsync(string source, CancellationToken ct = default); Task RestaurerAsync(string source, CancellationToken ct = default); }
